"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["56793"],{65933(e){e.exports=JSON.parse('{"id":"FIN-1099","slug":"abandonment-option","term":"Abandonment Option","also_known_as":[],"difficulty":"Advanced","definition":"An abandonment option is a company\'s ability to stop a project before its planned end, and recover some value by selling assets or cutting losses, if the project performs worse than expected.","explanation":["The abandonment option is a type of real option. It limits the downside of an investment, much like an insurance policy, because if things go badly, the company is not forced to keep losing money.","For example, a company opens a new mine. If metal prices fall sharply, it can close the mine and sell its equipment for 400,000, rather than continuing to operate at a loss. The possibility of recovering this value makes the project less risky and more valuable than a traditional analysis assuming the company must operate for the full term.","The value of an abandonment option depends on how much can be recovered and how uncertain the project\'s outcomes are. Projects using general-purpose assets, such as buildings or vehicles that can easily be sold, usually have more valuable abandonment options than those using highly specialized equipment.","Ignoring abandonment options can lead companies to undervalue risky projects. Recognising them encourages designing projects with flexibility built in."],"note":"","total":1500,"prev":{"slug":"401-k","term":"401(k)"},"next":{"slug":"absolute-advantage","term":"Absolute Advantage"}}')}}]);